export const SUPPLY = 150;

/** Wei per table unit (1 microether). */
const UNIT = 1_000_000_000_000n;

/** Price of mint #n (index n − 1) in microether. */
export const PRICE_MICRO: readonly number[] = [1000, 1047, 1097, 1149, 1204, 1261, 1321, 1383, 1449, 1518, 1590, 1665, 1744, 1827, 1914, 2005, 2100, 2199, 2304, 2413, 2527, 2647, 2773, 2905, 3042, 3187, 3338, 3496, 3662, 3836, 4018, 4209, 4409, 4618, 4837, 5066, 5307, 5559, 5822, 6099, 6388, 6691, 7009, 7341, 7690, 8055, 8437, 8837, 9256, 9696, 10160, 10640, 11140, 11670, 12220, 12810, 13410, 14050, 14720, 15410, 16150, 16910, 17710, 18550, 19440, 20360, 21320, 22340, 23400, 24510, 25670, 26890, 28160, 29500, 30900, 32360, 33900, 35510, 37190, 38960, 40810, 42740, 44770, 46900, 49120, 51450, 53890, 56450, 59130, 61940, 64880, 67950, 71180, 74560, 78090, 81800, 85680, 89750, 94010, 98470, 103100, 108000, 113200, 118500, 124200, 130000, 136200, 142700, 149500, 156500, 164000, 171800, 179900, 188400, 197400, 206700, 216600, 226800, 237600, 248900, 260700, 273000, 286000, 299600, 313800, 328700, 344300, 360600, 377700, 395700, 414400, 434100, 454700, 476300, 498900, 522500, 547300, 573300, 600500, 629000, 658900, 690100, 722900, 757200, 793100, 830700, 870200, 911400, 954700, 1000000];

/** Price in wei of mint number `n` (1-based). */
export function priceWei(n: number): bigint {
    const v = PRICE_MICRO[n - 1];
    if (v === undefined) throw new RangeError(`No mint #${n}`);
    return BigInt(v) * UNIT;
}

/** Total in wei of `quantity` mints starting at mint number `first`. */
export function quoteWei(first: number, quantity: number): bigint {
    let total = 0n;
    for (let n = first; n < first + quantity; n++) total += priceWei(n);
    return total;
}

/** Price of mint #n in ETH, for display and charts. */
export function priceEth(n: number): number {
    return PRICE_MICRO[n - 1] / 1_000_000;
}

/** What selling out raises, in ETH. */
export const SELL_OUT_ETH = 22.052777;
